import{c as l,Q as a,j as s,m as o}from"./chunks/framework.DOi4mjdC.js";const e="/assets/zh-cn_image_0000002409729950.GmYt9xOy.png",n="/assets/zh-cn_image_0000002381161446.CDFZuliY.png",p="/assets/zh-cn_image_0000002409891270.NaOX_DCd.png",i="/assets/zh-cn_image_0000002443251985.uACeCoNA.png",u="/assets/zh-cn_image_0000002381162386.B-CYSHaz.png",g="/assets/zh-cn_image_0000002414561861.Ba4iF_hx.png",_=JSON.parse('{"title":"AIV核上的ND2NZ格式转换","description":"","frontmatter":{},"headers":[{"level":1,"title":"AIV核上的ND2NZ格式转换","slug":"aiv核上的nd2nz格式转换"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/AIV核上的ND2NZ格式转换.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/AIV核上的ND2NZ格式转换.md"}'),r={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/AIV核上的ND2NZ格式转换.md"};function c(d,t,q,h,b,N){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="aiv核上的nd2nz格式转换" tabindex="-1">AIV核上的ND2NZ格式转换 <a class="header-anchor" href="#aiv核上的nd2nz格式转换" aria-label="Permalink to &quot;AIV核上的ND2NZ格式转换&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例展示了在矩阵乘算子场景中，使用Matmul高阶API进行计算，对内轴（内轴即矩阵的行方向）非256字节对齐的输入矩阵，在AIV核上进行ND2NZ格式转换对算子性能提升的效果。为提升Cube单元的计算效率，ND格式的输入矩阵在执行Cube计算前会先转换为NZ格式，ND格式和NZ格式的具体内容可参考<a href="./../../SIMT算子实现/基础知识.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>。Matmul API内部使用随路ND2NZ指令同时进行格式转换以及数据搬运。但在数据非256字节对齐时，<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E9%9A%8F%E8%B7%AF%E8%BD%AC%E6%8D%A2ND2NZ%E6%90%AC%E8%BF%90.md" target="_blank" rel="noreferrer">随路ND2NZ指令</a>存在带宽利用率低的问题。因此输入矩阵的内轴非256字节对齐时，在进行Matmul计算前，利用AIV核上Vector计算单元完成ND格式到NZ格式的转换，可以避免随路非对齐数据搬运存在的效率低的问题，从而提升算子性能。</p><ul><li><p>AIV核上的ND2NZ格式转换的适用场景</p><p>输入矩阵内轴非256字节对齐，且数据量较大影响随路格式转换的效率。</p></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;1024, 1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;1024, 4095&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，算子中使能高阶API Matmul的纯Cube模式。使用MDL模板，Tiling参数如下：</p><ul><li>原始shape：M=1024, N= 4095, K=1024。</li><li>单核shape：singleCoreM=128，singleCoreN=1408，singleCoreK=1024。</li><li>基本块shape：baseM=128，baseN=256，baseK=64。</li><li>L1缓存相关Tiling参数：stepM=1，stepN=1，stepKa=4，stepKb=4。</li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据，重点分析MTE2的流水。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li>优化前的Cube流水图如下，由于使用了随路ND2NZ指令，在MTE2数据搬运过程中进行数据格式的转换，导致MTE2整体占比较高。<img src="'+e+'" alt=""></li><li>优化前的Profiling数据如下，可以看到只使用Cube单元执行计算，aic_time最大耗时149.04us，其中aic_mte2_ratio占比很高。<img src="'+n+`" alt=""></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>对于ND格式的输入矩阵，不再使用随路ND2NZ指令进行格式转换，而是利用Vector计算单元的能力完成数据格式转换。首先使用DataCopyPad接口，将非对齐的矩阵数据搬入Unified Buffer，使用Duplicate接口填充需要补为对齐位置的数据，再逐行调用Copy接口实现数据从ND到NZ格式的重排，将重排后的NZ数据写入workspace内存，最后直接读取workspace上的NZ数据，进行Matmul计算。</p><p>实现AIV核上的ND2NZ格式转换的主要步骤如下：</p><ol><li><p>创建Matmul对象时，定义内轴非256字节对齐的B矩阵的Format为NZ格式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, ATYPE, true&gt;;</span></span>
<span class="line"><span>// 使用CubeFormat::NZ定义矩阵B的类型信息</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, AscendC::TPosition::GM, CubeFormat::NZ, BType, true&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_MDL&gt; matmulObj;</span></span></code></pre></div></li><li><p>利用Vector计算单元实现ND2NZ格式转换。如下代码中MatrixBtoNZ为将B矩阵的ND格式转换为NZ格式的函数，该函数的具体实现请参考完整样例代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Vector ND2NZ</span></span>
<span class="line"><span>if ASCEND_IS_AIV {</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(ubBuf, TOTAL_UB_SIZE);</span></span>
<span class="line"><span>    MatrixBtoNZ&lt;typename B_TYPE::T&gt;(tempGM, bGMNZ, tiling, isTransB, ubBuf, tiling.baseK,</span></span>
<span class="line"><span>        tiling.baseN); // ND2NZ格式转换函数</span></span>
<span class="line"><span>    SyncAll();</span></span>
<span class="line"><span>    // CV SYNC</span></span>
<span class="line"><span>    NotifyEvent&lt;PIPE_MTE3&gt;(4);</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>if ASCEND_IS_AIC {</span></span>
<span class="line"><span>    WaitEvent(4); // 等待Vector完成ND2NZ格式转换</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>设置左矩阵A、右矩阵B、Bias，完成矩阵乘操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>matmulObj.SetTail(tailM, tailN, shapes.k);</span></span>
<span class="line"><span>matmulObj.SetTensorA(aGlobal, false);</span></span>
<span class="line"><span>matmulObj.SetTensorB(bGlobal, false);</span></span>
<span class="line"><span>if (shapes.isBias) {</span></span>
<span class="line"><span>    matmulObj.SetBias(biasGlobal);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>matmulObj.IterateAll(cGlobal);</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li>优化后的Vector流水图如下所示，利用Vector计算单元的能力，完成B矩阵的数据格式转换。<img src="`+p+'" alt=""></li><li>优化后的Cube流水图如下所示，不使用随路ND2NZ指令对B矩阵进行格式转换后，MTE2的占比明显下降。<img src="'+i+'" alt=""></li><li>优化后的Profiling数据如下，可以看到同时使用Cube单元和Vector单元，aic_time最大耗时90.95us，其中aic_mte2_ratio占比明显降低。<img src="'+u+'" alt=""><img src="'+g+'" alt=""></li></ul><p><strong>表 2</strong> 端到端性能对比</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;22.61%&quot;&gt;&lt;p&gt;优化方法&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.88%&quot;&gt;&lt;p&gt;总耗时(us)&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.729999999999997%&quot;&gt;&lt;p&gt;AIC_MTE2平均耗时(us)&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.78%&quot;&gt;&lt;p&gt;AIV_MTE2平均耗时(us)&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;22.61%&quot;&gt;&lt;p&gt;随路ND2NZ&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.88%&quot;&gt;&lt;p&gt;149.82&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.729999999999997%&quot;&gt;&lt;p&gt;130.77&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.78%&quot;&gt;&lt;p&gt;0&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;22.61%&quot;&gt;&lt;p&gt;Vector侧ND2NZ&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.88%&quot;&gt;&lt;p&gt;93.76&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25.729999999999997%&quot;&gt;&lt;p&gt;22.85&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.78%&quot;&gt;&lt;p&gt;10.31&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>从上表中执行时间的对比，可以看出：不使用随路ND2NZ指令后，总耗时大幅下降，端到端性能提升明显。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>对于矩阵乘计算中矩阵内轴非256字节对齐的场景，随路ND2NZ指令的带宽利用率低，影响算子性能，通过在AIV核上进行ND2NZ的数据重排，提升算子整体性能。值得注意的是，带宽利用率与数据量有关，如果矩阵数据总量太小，即使是在AIV核上进行的ND2NZ转换也无法明显提升有效带宽，反而会因为引入了多核同步，导致算子端到端的性能劣化。</p>',24)])])}const v=l(r,[["render",c]]);export{_ as __pageData,v as default};
